// THROWAWAY Sources study: alternatives only, no mutations or client science.
import {cssVars} from './sky-tokens.js';
import {normalize} from './sources-data.js';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={A:'Source ledger',B:'Family finder',C:'Coverage lanes'};
const hypotheses={A:'Start with the source. Scan registry, retrieval and temporal evidence in one ledger.',B:'Start with a field family. Compare declared fields across sources, with temporal evidence kept separate.',C:'Start with time. See retained-run samples and published layer frames beside the full catalogue.'};
const q=new URLSearchParams(location.search), stamp=t=>t!=null&&Number.isFinite(typeof t==='number'?t:Date.parse(t))?new Date(t).toISOString().replace('T',' ').replace(':00.000Z','Z'): 'Not supplied';
const pretty=s=>String(s??'unknown').replaceAll('_',' '), unique=a=>[...new Set(a)], same=(a,b)=>Date.parse(a)===Date.parse(b);
const validInstant=q.get('instant')&&Number.isFinite(Date.parse(q.get('instant')))?new Date(q.get('instant')).toISOString():null;
const state={variant:['A','B','C'].includes(q.get('variant'))?q.get('variant'):'A',focus:q.get('focus')==='point'?'point':'site',instant:validInstant,theme:['light','dark','night'].includes(q.get('theme'))?q.get('theme'):'light',cv:'normal',mode:'capture',family:'all',registry:'all',search:'',filter:'all',selection:null,range:'core'};
let T,capture,live={requests:{}},pending=false,sequence=0,model,timelineTimes=[];
const bundle=()=>state.mode==='capture'?capture:state.mode==='live'?live:{requests:{}};
const sourceColor=r=>`var(--src-${T.palettes.light.C.sources.find(s=>s.sources.includes(r.id))?.slot??8})`;
const sourceTag=r=>`<span class="source-id" style="--source-color:${sourceColor(r)}"><i class="source-dot" aria-hidden="true"></i>${esc(r.id)}</span>`;
function glyph(r){const cls=r.evidenceClasses.length===1?r.evidenceClasses[0]:'unrecognised';const known=['retrieved','reprocessed','derived_here','intermediary_derived','generated_display','uncalibrated_observation'];return `<svg class="glyph" role="img" aria-label="${esc(known.includes(cls)?pretty(cls):'Evidence class not supplied')}"><use href="#g-${known.includes(cls)?cls:'unrecognised'}"/></svg>`}
const chip=(x,warn=false)=>`<span class="chip ${warn?'warn':''}">${esc(x??'unknown')}</span>`;
function sourceButton(r){return `<button class="source-button" data-inspect="${esc(r.id)}" aria-label="Inspect ${esc(r.source.product)}"><span>${glyph(r)}</span><span><strong>${esc(r.source.product)}</strong><small>${sourceTag(r)}</small></span></button>`}
const textState={unavailable:'Timeline unavailable',unsampled:'No exact timeline item','retained-run-coverage':'Retained run at instant','product-listed':'Product listed; no retained run','aged-out':'Aged out at instant','no-retained-coverage':'No retained run at instant',unknown:'Coverage unresolved'};
function temporal(r){return textState[r.temporalState]??'Coverage unresolved'}
function runLabel(r){const values=r.runAssessments.map(x=>x.run_stale);return values.some(x=>x===true)?'Run stale reported':values.length&&values.every(x=>x===false)?'Runs reported current':'Run staleness unknown'}
function filtered(){const s=state.search.trim().toLowerCase();return model.records.filter(r=>(state.family==='all'||r.families.includes(state.family))&&(state.registry==='all'||r.source.state===state.registry)&&(!s||[r.id,r.source.product,r.source.producer].join(' ').toLowerCase().includes(s))&&(state.filter==='all'||state.filter==='retained'&&r.coverage.length||state.filter==='stale'&&r.status?.freshness?.status==='stale'||state.filter==='aged'&&r.agedAtFocus))}
function licence(r){const text=r.source.licence??'Licence not supplied';return `<details class="licence-note"><summary>${esc(text.length>90?text.slice(0,90)+'…':text)}</summary><p>${esc(text)}</p><p>${esc(r.source.attribution)}</p></details>`}
function registryCell(r){return `${chip(r.source.state)}<small class="registry-reason">${esc(r.source.status_reason)}</small>`}
function freshnessCell(r){return `${chip(r.status?.freshness?.status??'unknown',r.status?.freshness?.status==='stale')}<small>Retrieved ${esc(stamp(r.status?.last_retrieval))}</small><small>${esc(runLabel(r))}</small>`}
function temporalCell(r){return `${chip(temporal(r))}<small>${r.layers.length} mapped layers · ${r.layerAtFocus.filter(l=>l.state==='exact-frame').length} with an exact frame</small>${r.agedOut?`<small>Aged-out declaration: ${esc(stamp(r.lastValidTime))}</small>`:''}`}
function variantA(rows){return `<div class="table-wrap" tabindex="0" role="region" aria-label="Source ledger, scroll for all columns"><table class="ledger"><caption>Every matching catalogue source. Registry state is independent of retrieval status. Counts describe returned metadata.</caption><thead><tr><th scope="col">Source / class</th><th scope="col">Registry state</th><th scope="col">Retrieval / run</th><th scope="col">At the shared instant</th><th scope="col">Licence / attribution</th></tr></thead><tbody>${rows.map(r=>`<tr class="${state.selection===r.id?'selected-row':''}"><th scope="row">${sourceButton(r)}<small>${esc(r.source.producer)}</small></th><td>${registryCell(r)}</td><td>${freshnessCell(r)}</td><td>${temporalCell(r)}</td><td>${licence(r)}</td></tr>`).join('')}</tbody></table></div>`}
function variantB(rows){
 if(state.family==='all')return `<div class="family-intro"><h2>Which family are you looking for?</h2><p>Choose a declared family to inspect its field-by-source matrix. “Stored” is registry metadata; it does not prove a field is available at this Focus.</p></div><div class="family-directory">${model.families.map(f=>{const rr=rows.filter(r=>r.families.includes(f));return `<button class="family-tile" data-family="${esc(f)}"><span class="eyebrow">Declared family</span><h3>${esc(pretty(f))}</h3><span class="count">${rr.length}</span><small>matching sources · ${model.endpoints.timeline.ok&&model.focusItem?rr.filter(r=>r.coverage.length).length+' with a retained run at instant':'temporal coverage unknown'}</small></button>`}).join('')}</div>`;
 const fields=unique(rows.flatMap(r=>r.fields.filter(f=>f.family===state.family).map(f=>f.key)));
 return `<div class="family-workbench"><nav class="family-nav" aria-label="Field families"><button data-family="all">All families</button>${model.families.map(f=>`<button data-family="${esc(f)}" aria-pressed="${f===state.family}">${esc(pretty(f))}</button>`).join('')}</nav><div><div class="family-intro"><h2>${esc(pretty(state.family))}</h2><p>${fields.length} declared fields across ${rows.length} matching sources. A family groups related quantities; it does not make them interchangeable.</p></div><div class="legend"><span>■ Stored declaration</span><span>□ Other storage declaration</span><span>— No mapping returned</span></div><div class="table-wrap" tabindex="0" role="region" aria-label="Field by source matrix, scroll horizontally"><table class="matrix"><caption>Cells show catalogue storage declarations. Header chips show source-level temporal evidence, not field availability.</caption><thead><tr><th scope="col">Field / storage</th>${rows.map(r=>`<th scope="col">${sourceButton(r)}${chip(temporal(r))}<small>${esc(r.source.state)}</small></th>`).join('')}</tr></thead><tbody>${fields.map(key=>`<tr><th scope="row">${esc(key)}</th>${rows.map(r=>{const f=r.fields.find(f=>f.key===key&&f.family===state.family);return `<td>${f?`<button class="cell" data-inspect="${esc(r.id)}" aria-label="Inspect ${esc(key)} from ${esc(r.id)}"><span class="cell-mark" aria-hidden="true">${f.storage==='stored'?'■':'□'}</span>${esc(f.storage)}<small>${esc(f.note??'No mapping note')}</small></button>`:'<span class="unknown">— No mapping returned</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="hint">Licence, registry reason, source freshness and the complete mapping are in the docked inspector. Source-wide run coverage does not establish coverage for an individual field or coordinate.</p></div></div>`;
}
function lanePoints(r){return {coverage:model.timeline.filter(t=>(t.coverage??[]).some(c=>c.source_id===r.id)).map(t=>t.valid_time_utc),aged:model.timeline.filter(t=>t.aged_out_sources?.[r.id]).map(t=>t.valid_time_utc),layers:unique(r.layers.flatMap(l=>l.times??[]))}}
function variantC(rows){
 const raw=model.endpoints.timeline.response??{}, start=Date.parse(raw.start),end=Date.parse(state.range==='core'?(raw.boundary??raw.end):raw.end);
 const rangeValid=Number.isFinite(start)&&Number.isFinite(end)&&end>start;
 const at=t=>100*(Date.parse(t)-start)/(end-start),inside=t=>rangeValid&&at(t)>=0&&at(t)<=100;
 const lanes=rows.map(r=>({r,p:lanePoints(r)})).filter(({p})=>Object.values(p).some(a=>a.some(inside)));
 function track(times,type){const marks=times.filter(inside);return `<div class="track">${marks.map(t=>`<span class="track-marker ${type}" style="left:${at(t)}%" title="${esc(stamp(t))}"></span>`).join('')}${inside(state.instant)?`<span class="focus-line" style="left:${at(state.instant)}%"></span>`:''}</div>`}
 return `<div class="lanes-layout"><section class="catalogue-rail"><h2>Full matching catalogue</h2><small>${rows.length} sources, including those without plotted evidence.</small><div class="catalogue-list">${rows.map(r=>sourceButton(r)).join('')}</div></section><section><div class="lane-head"><div><h2>Temporal evidence</h2><small>${lanes.length} sources with marks in this window</small></div><label for="lane-range">Window <select id="lane-range"><option value="core" ${state.range==='core'?'selected':''}>Core tier</option><option value="full" ${state.range==='full'?'selected':''}>Full timeline</option></select></label></div><div class="legend"><span>■ Retained run sample</span><span>│ Layer frame (stored or proxy)</span><span>◇ Aged-out declaration</span><span>Coloured rule: shared instant</span></div><p class="hint">Marks show exact returned times; gaps stay empty. Layer frames are not retained-run coverage. Live-proxy frames do not establish stored evidence. Select a source for each layer's basis, run and request.</p>${rangeValid?`<div class="axis"><span>${stamp(start)}</span><span>${stamp(end)}</span></div>`:''}${lanes.length?lanes.map(({r,p})=>`<section class="lane" style="--source-color:${sourceColor(r)}"><div class="lane-label">${sourceButton(r)}${chip(temporal(r))}</div>${[['coverage','Retained run',''],['layers','Layer frames','layer'],['aged','Aged out','aged']].map(([key,label,style])=>`<div class="track-row"><span>${label}</span>${track(p[key],style)}</div>`).join('')}<details><summary>Exact times and layer basis</summary><pre>${esc(JSON.stringify({retained_run_samples:p.coverage,aged_out_samples:p.aged,layers:r.layers.map(l=>({id:l.id,evidence_basis:l.evidence_basis,times:l.times}))},null,2))}</pre></details></section>`).join(''):`<div class="empty">${rangeValid?'No exact temporal marks from mapped sources in this window. The catalogue remains available at left.':'Timeline unavailable; no time axis or coverage marks can be drawn.'}</div>`}</section></div>`;
}
function renderNotices(){
 $('#notices-label').textContent=`API notices · ${model.notices.length} returned · ${model.unmatchedLayers.length} unmapped layers`;
 $('#notices-body').innerHTML=Object.entries(model.endpoints).map(([name,e])=>`<section><h3>${esc(name)} · ${e.ok?'HTTP '+e.status:'unavailable'}</h3><p>${esc(e.error??'Read completed')} · ${esc(e.response?.data_mode??'No data mode')} · ${esc(stamp(e.completed_at))}</p><ul>${(e.ok?e.response?.notices??[]:[]).map(n=>`<li>${esc(n)}</li>`).join('')||'<li>No notices returned.</li>'}</ul></section>`).join('')+`<section><h3>Unmapped layers</h3><p>${model.unmatchedLayers.length} layer products lack a verified source join in this study. They are preserved here, not assigned by a guessed name.</p>${model.unmatchedLayers.map(l=>`<details><summary>${esc(l.title)} · ${esc(l.product)}</summary><pre>${esc(JSON.stringify(l,null,2))}</pre></details>`).join('')}</section><section><h3>Focus timeline item</h3><pre>${esc(JSON.stringify(model.focusItem??{notice:'No exact timeline item at Focus'},null,2))}</pre></section>`;
}
const dl=items=>`<dl>${items.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v??'Not supplied')}</dd>`).join('')}</dl>`;
const rawDetails=(label,x)=>`<details><summary>${esc(label)}</summary><pre>${esc(JSON.stringify(x,null,2))}</pre></details>`;
function renderInspector(){
 const aside=$('#inspector');aside.hidden=!state.selection;$('.shell').classList.toggle('inspect-open',Boolean(state.selection));if(!state.selection)return;
 const r=model.records.find(r=>r.id===state.selection);$('#inspect-title').textContent=r?.source.product??state.selection;
 if(!r){$('#inspect-content').innerHTML='<p>Selected source is unavailable in this response. No saved source evidence is substituted. Return to the saved capture explicitly to inspect it.</p>';return}
 $('#inspect-content').innerHTML=`<p>${glyph(r)} ${sourceTag(r)}</p><p>${esc(r.source.producer)} declares this source ${esc(r.source.state)}. Retrieval is ${esc(r.status?.freshness?.status??'unknown')}. ${esc(temporal(r))}. Location coverage is not established.</p>${dl([['Evidence class',r.evidenceClasses.join(', ')||'Not supplied; not inferred from delivery kind'],['Delivery kind',r.source.delivery_kind],['Intermediary',r.source.intermediary??'None declared'],['Registry reason',r.source.status_reason],['Role',r.source.role],['Retrieval detail',r.status?.detail],['Last retrieval',stamp(r.status?.last_retrieval)],['Retrieval age at request',r.status?.freshness?.age_seconds==null?'Unknown':r.status.freshness.age_seconds+' seconds'],['Freshness threshold',r.status?.freshness?.threshold_seconds==null?'Unknown':r.status.freshness.threshold_seconds+' seconds'],['Run staleness',runLabel(r)],['Aged out at Focus',r.agedAtFocus?stamp(r.agedAtFocus):'No declaration at Focus'],['Layer endpoint aged-out declaration',r.agedAtLayers?stamp(r.agedAtLayers):'None returned'],['Geographic coverage (registry)',r.source.geographic_coverage],['Cadence (registry)',r.source.cadence],['Forecast horizon (registry)',r.source.forecast_horizon]])}<h3>Licence and attribution</h3>${dl([['Licence',r.source.licence],['Attribution',r.source.attribution],['Caching',r.source.caching],['Archival',r.source.archival],['Redistribution',r.source.redistribution],['Documentation',r.source.documentation_url]])}<h3>Fields and method context</h3><p class="hint">These endpoints provide registry metadata, not per-reading provenance. Quality, sample geometry, per-value method/inputs and comparability are not established here. Field mapping notes follow verbatim.</p>${r.fields.map(f=>rawDetails(`${f.key} · ${f.storage}`,f)).join('')||'<p>No field mappings returned.</p>'}<h3>Mapped layers</h3>${r.layers.map(l=>`<details><summary>${esc(l.title)}</summary>${dl([['Product',l.product],['Source join',r.productMatches.find(m=>m.layer_id===l.id)?.basis],['Evidence basis',l.evidence_basis],['Semantics',l.semantics],['Run time',stamp(l.run_time)],['Run stale',l.run_stale==null?'Unknown':String(l.run_stale)],['Run stale reason',l.run_stale_reason],['At Focus',r.layerAtFocus.find(x=>x.layer_id===l.id)?.state]])}<pre>${esc(JSON.stringify(l,null,2))}</pre></details>`).join('')||'<p>No verified layer-to-source mapping in this response.</p>'}<h3>Temporal evidence and notices</h3>${rawDetails('Source coverage and run assessments',{temporalState:r.temporalState,coverage:r.coverage,availableProducts:r.availableProducts,runAssessments:r.runAssessments})}${rawDetails('Complete timeline item at Focus',model.focusItem)}${rawDetails('All response notices (endpoint scope)',model.notices)}<h3>Capture provenance</h3><p class="hint">${state.mode==='capture'?'Historical API capture':'Current read session'}. Four independent requests; no shared evidence revision. Returned freshness ages are not recomputed by the client.</p>${rawDetails('Request URLs, times, status and data mode',Object.fromEntries(Object.entries(model.endpoints).map(([k,e])=>[k,{request_url:e.request_url,requested_at:e.requested_at,completed_at:e.completed_at,status:e.status,error:e.error,data_mode:e.response?.data_mode}])))}${rawDetails('Complete source records',r.raw)}${rawDetails('Missing metadata',r.missingMetadata)}`;
}
function updateStatePanel(){ $('#state').textContent=JSON.stringify({...state,coordinates:state.focus==='site'?{lat:47.5704,lon:-52.6816}:{lat:47.5615,lon:-52.7126},operational:false,endpointScope:'Global catalogue/status/layers and temporal timeline; no coordinate sampling',familyBasis:model.familyBasis,requests:Object.fromEntries(Object.entries(model.endpoints).map(([k,e])=>[k,{url:e.request_url,requested_at:e.requested_at,completed_at:e.completed_at,status:e.status,error:e.error}]))},null,2)}
function options(id,values,current,label){$('#'+id).innerHTML=`<option value="all">${label}</option>`+values.map(v=>`<option value="${esc(v)}">${esc(pretty(v))}</option>`).join('');if(current!=='all'&&!values.includes(current))$('#'+id).insertAdjacentHTML('beforeend',`<option value="${esc(current)}">${esc(pretty(current))} (not in response)</option>`);$('#'+id).value=current}
function render(){
 model=normalize(bundle(),state.instant);timelineTimes=model.timeline.map(t=>t.valid_time_utc).filter(t=>Number.isFinite(Date.parse(t))).sort((a,b)=>Date.parse(a)-Date.parse(b));
 if(!state.instant)state.instant=timelineTimes[0]??new Date().toISOString();model=normalize(bundle(),state.instant);
 for(const [k,v] of Object.entries(cssVars(T,'C',state.theme)))document.documentElement.style.setProperty(k,v);document.documentElement.style.colorScheme=state.theme==='light'?'light':'dark';document.body.dataset.cv=state.cv;
 for(const id of ['focus','theme','mode'])$('#'+id).value=state[id];$('#vision').value=state.cv;
 $('#focus-meta').textContent=(state.focus==='site'?'47.5704, −52.6816':'47.5615, −52.7126')+' · Source availability at this coordinate is not established';
 $('#heading').textContent=names[state.variant];$('#hypothesis').textContent=hypotheses[state.variant];$('#variant-label').textContent=state.variant+' · '+names[state.variant];$('#refresh').disabled=pending;
 const failed=Object.entries(model.endpoints).filter(([,e])=>!e.ok).map(([name])=>name);
 $('#notice').textContent=(pending?'Reading API…':state.mode==='capture'?`HISTORICAL CAPTURE · ${stamp(capture.captured_at)}`:state.mode==='outage'?'UNAVAILABLE STATE STUDY · no source evidence':'LIVE READ SESSION · '+stamp(live.captured_at))+' · '+(failed.length?`Unavailable: ${failed.join(', ')}. `:'')+'Four independent requests; no atomic revision. Nothing here promotes a registry state.';
 options('family',model.families,state.family,'All families');options('registry',unique(model.records.map(r=>r.source.state)).sort(),state.registry,'All registry states');$('#evidence-filter').value=state.filter;
 const rows=filtered();const coverageCount=model.endpoints.timeline.ok&&model.focusItem?`${rows.filter(r=>r.coverage.length).length} with retained-run coverage at Focus`:'Retained-run coverage at Focus unknown';$('#result-count').textContent=model.endpoints.catalog.ok?`${rows.length} of ${model.records.length} catalogue sources · ${coverageCount}`:'Catalogue unavailable · source count unknown';
 $('#stage').className=state.variant;
 $('#stage').innerHTML=rows.length?({A:variantA,B:variantB,C:variantC}[state.variant])(rows):`<div class="empty">${model.endpoints.catalog.ok?'No sources match these filters. Clear filters to return to the full catalogue.':'Catalogue unavailable. Source rows cannot be shown from this read. Choose Saved API capture explicitly to return to historical evidence.'}</div>`;
 const choices=unique([...timelineTimes,state.instant].map(t=>new Date(t).toISOString())).sort((a,b)=>Date.parse(a)-Date.parse(b));$('#instant').innerHTML=choices.map(t=>`<option value="${esc(t)}">${esc(stamp(t))}${timelineTimes.some(x=>same(x,t))?'':' · not sampled'}</option>`).join('');$('#instant').value=new Date(state.instant).toISOString();
 const idx=timelineTimes.findIndex(t=>same(t,state.instant));$('#time-slider').max=Math.max(0,timelineTimes.length-1);$('#time-slider').value=idx<0?0:idx;$('#time-slider').disabled=timelineTimes.length<2;$('#time-slider').setAttribute('aria-valuetext',idx<0?'Focus is outside exact timeline samples':stamp(state.instant));
 $('#tier').textContent=model.focusItem?.tier??'No exact timeline item';$('#range-start').textContent=timelineTimes.length?stamp(timelineTimes[0]):'Timeline unavailable';$('#range-end').textContent=timelineTimes.length?stamp(timelineTimes.at(-1)):'';$('#rail-note').textContent=idx<0?'Focus is not on a returned sample':'Exact returned timeline items';$('#local-time').textContent=new Date(state.instant).toLocaleString('en-CA',{timeZone:'America/St_Johns'})+' · Newfoundland';
 for(const k of ['variant','focus','instant'])q.set(k,state[k]);history.replaceState(null,'','?'+q);renderNotices();renderInspector();updateStatePanel();
}
async function readLive(){
 const seq=++sequence;state.mode='live';pending=true;live={requests:{},captured_at:new Date().toISOString()};render();
 const requests=await Promise.all(Object.entries({catalog:'catalog',status:'sources/status',timeline:'timeline',layers:'layers'}).map(async([key,path])=>{
  const request_url='/api/experiments/weather/v0/'+path,requested_at=new Date().toISOString();let status=null,response=null,error=null;
  try{const r=await fetch(request_url,{signal:AbortSignal.timeout(65000)});status=r.status;const text=await r.text();try{response=JSON.parse(text)}catch{error='Response is not JSON'}if(!r.ok)error=`HTTP ${r.status}`;}catch(e){error=e.message}
  return[key,{request_url,requested_at,completed_at:new Date().toISOString(),status,response,error}];
 }));if(seq!==sequence)return;live={captured_at:new Date().toISOString(),requests:Object.fromEntries(requests)};pending=false;render();
}
function cycle(n){state.variant=['A','B','C'][(['A','B','C'].indexOf(state.variant)+n+3)%3];render()}
$('#previous').onclick=()=>cycle(-1);$('#next').onclick=()=>cycle(1);
$('#focus').onchange=e=>{state.focus=e.target.value;render()};$('#theme').onchange=e=>{state.theme=e.target.value;render()};$('#vision').onchange=e=>{state.cv=e.target.value;render()};
$('#mode').onchange=e=>{state.mode=e.target.value;if(state.mode==='live')readLive();else{sequence++;pending=false;render()}};$('#refresh').onclick=readLive;
$('#instant').onchange=e=>{state.instant=e.target.value;render()};$('#time-slider').oninput=e=>{state.instant=timelineTimes[Number(e.target.value)];render()};$('#now').onclick=()=>{state.instant=new Date().toISOString();render()};
$('#family').onchange=e=>{state.family=e.target.value;render()};$('#registry').onchange=e=>{state.registry=e.target.value;render()};$('#evidence-filter').onchange=e=>{state.filter=e.target.value;render()};$('#search').oninput=e=>{state.search=e.target.value;render()};$('#clear').onclick=()=>{Object.assign(state,{family:'all',registry:'all',filter:'all',search:''});$('#search').value='';render()};
$('#close-inspector').onclick=()=>{const id=state.selection;state.selection=null;document.querySelectorAll('.selected-row').forEach(tr=>tr.classList.remove('selected-row'));renderInspector();updateStatePanel();const opener=[...document.querySelectorAll('[data-inspect]')].find(e=>e.dataset.inspect===id);(opener??$('#heading')).focus()};
document.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea,button,summary,[contenteditable]'))return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();cycle(e.key==='ArrowRight'?1:-1)}});
document.addEventListener('click',e=>{const inspect=e.target.closest('[data-inspect]'),family=e.target.closest('[data-family]');if(inspect){state.selection=inspect.dataset.inspect;document.querySelectorAll('.ledger tbody tr').forEach(tr=>tr.classList.toggle('selected-row',tr.querySelector('[data-inspect]')?.dataset.inspect===state.selection));renderInspector();updateStatePanel();if(matchMedia('(max-width:1199px)').matches)$('#inspector').scrollIntoView({block:'start'});}else if(family){state.family=family.dataset.family;render();$('#family').focus()}});
document.addEventListener('change',e=>{if(e.target.id==='lane-range'){state.range=e.target.value;render()}});
try{[T,capture]=await Promise.all(['tokens.json','sources-captures.json'].map(async p=>{const r=await fetch(p);if(!r.ok)throw Error(p+' HTTP '+r.status);return r.json()}));const font=document.createElement('link');font.rel='stylesheet';font.href='https://fonts.googleapis.com/css2?'+T.variants.C.fonts.google+'&display=swap';document.head.append(font);render()}catch(e){$('#notice').textContent='Study assets unavailable: '+e.message;$('#refresh').disabled=true;$('#stage').textContent='The prototype cannot load its assets. See the study notes for the local run command.'}
